435	{#if show}
436		<!-- #{#zom5a} Modal with proper ARIA attributes -->
437		<div
438			class="fixed inset-0 z-60 flex items-center justify-center bg-black/90 p-4"
439			onclick={handleBackdropClick}
440			onkeydown={handleBackdropKeydown}
