10	import { MIN_ZOOM, calculateFitDimensions, calculateMaxZoom } from './imageZoom';
11	
12	describe('calculateFitDimensions', () => {
13		it('shrinks an image larger than the viewport, preserving aspect ratio', () => {
14			// 4000x3000 into a 1800x1000 box — height is the binding constraint
15			const fit = calculateFitDimensions(4000, 3000, 1800, 1000);
16	
17			expect(fit.height).toBeCloseTo(1000, 5);
18			expect(fit.width / fit.height).toBeCloseTo(4000 / 3000, 5);
19		});
20	
21		it('uses width as the constraint for a wide image', () => {
22			const fit = calculateFitDimensions(4000, 1000, 1800, 1000);
23	
24			expect(fit.width).toBeCloseTo(1800, 5);
25			expect(fit.height).toBeCloseTo(450, 5);
26		});
27	
28		it('never enlarges an image that already fits', () => {
29			const fit = calculateFitDimensions(400, 300, 1800, 1000);
30	
31			expect(fit).toEqual({ width: 400, height: 300 });
32		});
33	
34		it('leaves an image exactly the size of the viewport alone', () => {
35			const fit = calculateFitDimensions(1800, 1000, 1800, 1000);
36	
37			expect(fit).toEqual({ width: 1800, height: 1000 });
38		});
39	});
