42		it('is the zoom at which one image pixel fills one CSS pixel', () => {
43			// Displayed at 900px wide from a 2400px source — 1:1 arrives at 266.67%
44			expect(calculateMaxZoom(2400, 900)).toBeCloseTo(266.667, 2);
45		});
46	
47		it('collapses to the minimum when the image is already shown at native size', () => {
48			expect(calculateMaxZoom(400, 400)).toBe(MIN_ZOOM);
49		});
