5	/**
6	 * Behaviour tests for the real <ReceiptImageViewer> zoom controls.
7	 *
8	 * The previous spec was hollow: every `it()` re-declared the zoom arithmetic
9	 * inline (`let zoom = 100; zoom += 50; expect(zoom).toBe(150)`) and asserted
10	 * against its own copy — 859 lines that passed no matter what the component did
11	 * (its header even admitted it was stale TDD RED-phase scaffolding). These render
12	 * the actual component and drive its buttons/keyboard, asserting the visible
13	 * zoom %, the disabled boundaries, and close wiring.
14	 *
15	 * The zoom ceiling is derived from each image's own resolution ("zoom never
16	 * invents pixels" — see the domain model), so these use SVG data URLs of a known
17	 * natural size rather than a URL that never loads. The arithmetic itself is
18	 * covered in `$lib/utils/imageZoom.spec.ts`; what matters here is the resulting
19	 * button state and that the image is never painted larger than it really is.
20	 *
21	 * Pointer gestures (wheel-zoom, drag-pan, pinch) stay a manual-verify item — they
22	 * use imperative `{ passive: false }` listeners that unit tests can't faithfully
23	 * drive (tracked in the backlog). The button + keyboard path is the deterministic,
24	 * render-testable surface, and it's where the real clamp/snap logic lives.
25	 */
26	
27	/** A loadable image of an exact natural size, with no network. */
28	function imageUrl(width: number, height: number): string {
29		const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><rect width="100%" height="100%" fill="#ccc"/></svg>`;
30		return `data:image/svg+xml;base64,${btoa(svg)}`;
31	}
32	
33	/** Bigger than any test viewport, so there is real headroom to zoom into. */
34	const LARGE = imageUrl(4000, 6000);
35	
36	/** Smaller than any test viewport, so it is already at native size at 100%. */
37	const SMALL = imageUrl(80, 60);
