41	/**
42	 * The <img> the viewer renders, once the browser has decoded it and the load
43	 * handler has sized it. The element is re-queried on each poll: the viewer swaps
44	 * the placeholder <img> for an explicitly-sized one once dimensions are known.
45	 */
46	async function loadedImage(screen: ReturnType<typeof render>): Promise<HTMLImageElement> {
47		return vi.waitUntil(() => {
48			const img = screen.container.querySelector('img');
49			return img?.style.width ? (img as HTMLImageElement) : false;
50		});
51	}
52	
53	describe('ReceiptImageViewer', () => {
54		it('renders nothing until show is true', async () => {
55			const screen = render(ReceiptImageViewer, { imageUrl: LARGE, show: false });
56			await expect.element(screen.getByRole('dialog')).not.toBeInTheDocument();
57		});
58	
59		it('opens at 100% with zoom-out disabled and zoom-in enabled', async () => {
60			const screen = render(ReceiptImageViewer, { ...props });
61	
62			await expect.element(screen.getByRole('dialog')).toBeVisible();
63			await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();
64			await expect.element(screen.getByRole('button', { name: 'Zoom out' })).toBeDisabled();
65			await expect.element(screen.getByRole('button', { name: 'Zoom in' })).toBeEnabled();
66		});
67	
68		it('steps up by 50% on each Zoom in click', async () => {
69			const screen = render(ReceiptImageViewer, { ...props });
70			await loadedImage(screen);
71	
72			await screen.getByRole('button', { name: 'Zoom in' }).click();
73			await expect.element(screen.getByText('150%', { exact: true })).toBeVisible();
74	
75			await screen.getByRole('button', { name: 'Zoom in' }).click();
76			await expect.element(screen.getByText('200%', { exact: true })).toBeVisible();
77		});
78	
79		it('stops zooming at the image’s own resolution and never paints it larger', async () => {
80			const screen = render(ReceiptImageViewer, { ...props });
81			const img = await loadedImage(screen);
82			const zoomIn = screen.getByRole('button', { name: 'Zoom in' });
83	
84			// Climb until the control turns itself off; the ceiling depends on the
