import { vi, type Mock } from 'vitest';

/**
 * Shared `globalThis.fetch` stubbing for specs that exercise a code path issuing a
 * single `fetch` (Bank of Canada rates in `ExchangeRateService`, the OCR endpoint in
 * `ReceiptService`). Centralises the `{ ok, json }` Response shape and the
 * `as unknown as typeof fetch` cast so a spec says what the endpoint returns, not how
 * to fake a Response.
 */

/** Minimal Response-like stub with a JSON body. `status` defaults from `ok`. */
export function jsonResponse(
	body: unknown,
	{ ok = true, status }: { ok?: boolean; status?: number } = {}
) {
	return { ok, status: status ?? (ok ? 200 : 500), json: () => Promise.resolve(body) };
}

/**
 * Replace `globalThis.fetch` with a mock resolving `body` as JSON and return the mock
 * (for `expect(...).toHaveBeenCalledWith(...)`). Pair with {@link installFetchMock} to
 * restore the real fetch afterwards.
 */
export function stubFetchJson(body: unknown, opts?: { ok?: boolean; status?: number }): Mock {
	const mock = vi.fn().mockResolvedValue(jsonResponse(body, opts));
	globalThis.fetch = mock as unknown as typeof fetch;
	return mock;
}

/** Replace `globalThis.fetch` with a rejecting mock (network error) and return it. */
export function stubFetchReject(error: Error = new Error('Network error')): Mock {
	const mock = vi.fn().mockRejectedValue(error);
	globalThis.fetch = mock as unknown as typeof fetch;
	return mock;
}

/**
 * Save the current `globalThis.fetch` and return a `restore()` that puts it back.
 * Call in `beforeEach`, invoke the result in `afterEach`.
 */
export function installFetchMock(): () => void {
	const original = globalThis.fetch;
	return () => {
		globalThis.fetch = original;
	};
}

