203	/**
204	 * Test Suite for Cleanup orphan storage on receipt insert failure
205	 *
206	 * Requirements:
207	 * - On any insert failure, the just-uploaded storage object must be removed before re-throwing
208	 * - The original insert error is what the caller sees — cleanup failure must NOT mask it
209	 * - If cleanup itself fails, the orphan path is logged via console.error('orphan_storage_cleanup_failed', ...)
210	 * - Storage upload failures (before insert) must NOT trigger a remove call
211	 * - Auto-categorization failures (after insert) must NOT trigger a remove call (the row exists)
212	 */
213	
214	describe('Cleanup orphan storage on insert failure', () => {
215		let mockUpload: ReturnType<typeof vi.fn>;
216		let mockRemove: ReturnType<typeof vi.fn>;
217		let mockInsertSingle: ReturnType<typeof vi.fn>;
218		let consoleErrorSpy: MockInstance<typeof console.error>;
219	
220		beforeEach(() => {
221			vi.clearAllMocks();
222			// Fake timers so withRetry's exponential backoff doesn't sleep for real seconds.
223			vi.useFakeTimers();
224			vi.mocked(isSuspiciousDate).mockReturnValue(false);
225	
226			mockUpload = vi.fn().mockResolvedValue({ error: null });
227			mockRemove = vi.fn().mockResolvedValue({ data: [], error: null });
228			const storageFromMock = vi.fn().mockReturnValue({ upload: mockUpload, remove: mockRemove });
229			(supabase.storage as { from: typeof supabase.storage.from }).from =
230				storageFromMock as unknown as typeof supabase.storage.from;
231	
232			// OCR fetch rejected → extract is null, no auto-cat path
233			stubFetchReject(new Error('no ocr in test'));
234	
235			mockInsertSingle = vi
236				.fn()
237				.mockResolvedValue({ data: { id: 'r1', family_id: null, merchant_name: null }, error: null });
238			const fromMock = vi.fn().mockReturnValue({
239				insert: vi.fn().mockReturnValue({
240					select: vi.fn().mockReturnValue({ single: mockInsertSingle })
241				})
242			});
243			(supabase as { from: typeof supabase.from }).from = fromMock as unknown as typeof supabase.from;
244	
245			consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
246		});
247	
248		afterEach(() => {
249			consoleErrorSpy.mockRestore();
250			vi.useRealTimers();
251		});
252	
253		type RetryOutcome<T> = { value?: T; error?: Error };
254	
255		// Helper: kick off uploadAndCreate, flush all pending retries via fake timers,
256		// and surface the resolved/rejected outcome as a Promise the test can assert on.
257		async function runWithRetries<T>(file: File): Promise<RetryOutcome<T>> {
258			const outcome: RetryOutcome<T> = {};
259			const settled = new ReceiptService(supabase)
260				.uploadAndCreate(file)
261				.then((v) => {
262					outcome.value = v as T;
263				})
264				.catch((e: unknown) => {
265					outcome.error = e instanceof Error ? e : new Error(String(e));
266				});
267			await vi.runAllTimersAsync();
268			await settled;
269			return outcome;
270		}
271	
272		it('does NOT call storage.remove on the happy path (insert succeeds)', async () => {
273			const file = new File(['x'], 'ok.jpg', { type: 'image/jpeg' });
274	
275			const { error } = await runWithRetries(file);
276			expect(error).toBeUndefined();
277			expect(mockUpload).toHaveBeenCalled();
278			expect(mockRemove).not.toHaveBeenCalled();
279		});
280	
281		it('calls storage.remove([path]) and re-throws original error when insert fails', async () => {
282			const insertError = new Error('insert failed: column does not exist');
283			// Permanent failure — withRetry exhausts all attempts
284			mockInsertSingle.mockResolvedValue({ data: null, error: insertError });
285	
286			const file = new File(['x'], 'fail.jpg', { type: 'image/jpeg' });
287			const { error } = await runWithRetries(file);
288	
289			expect(error).toBeDefined();
290			expect(error?.message).toContain('insert failed: column does not exist');
291	
292			expect(mockUpload).toHaveBeenCalled();
293			expect(mockRemove).toHaveBeenCalled();
294			// The remove call must include the same storage path that upload used
295			const uploadPath = mockUpload.mock.calls[0][0]; // first arg to upload()
296			expect(mockRemove).toHaveBeenCalledWith([uploadPath]);
297		});
298	
299		it('logs orphan_storage_cleanup_failed and STILL re-throws the original insert error when remove fails too', async () => {
300			const insertError = new Error('original insert failure');
301			const cleanupError = new Error('cleanup network blip');
302			mockInsertSingle.mockResolvedValue({ data: null, error: insertError });
303			mockRemove.mockResolvedValue({ data: null, error: cleanupError });
304	
305			const file = new File(['x'], 'doublefail.jpg', { type: 'image/jpeg' });
306			const { error } = await runWithRetries(file);
307	
308			// Original insert error wins — caller is NOT shown the cleanup error
309			expect(error).toBeDefined();
310			expect(error?.message).toContain('original insert failure');
311	
312			// Orphan path was logged for later reconciliation
313			const orphanLogs = consoleErrorSpy.mock.calls.filter(
314				(args) => args[0] === 'orphan_storage_cleanup_failed'
315			);
316			expect(orphanLogs.length).toBeGreaterThanOrEqual(1);
317			const payload = orphanLogs[0][1] as {
318				path: string;
319				insertError: unknown;
320				cleanupError: unknown;
321			};
322			expect(typeof payload.path).toBe('string');
323			expect(payload.path.length).toBeGreaterThan(0);
324			expect(payload.insertError).toBeDefined();
325			expect(payload.cleanupError).toBeDefined();
326		});
327	
328		it('does NOT call storage.remove when the upload itself fails (nothing to clean up)', async () => {
329			const uploadError = new Error('upload failed');
330			mockUpload.mockResolvedValue({ error: uploadError });
331	
332			const file = new File(['x'], 'noupload.jpg', { type: 'image/jpeg' });
333			const { error } = await runWithRetries(file);
334	
335			expect(error).toBeDefined();
336			expect(mockUpload).toHaveBeenCalled();
337			expect(mockRemove).not.toHaveBeenCalled();
338		});
339	
340		it('does NOT call storage.remove when auto-categorization fails (row already exists)', async () => {
341			// Set up a successful insert returning a family_id + merchant_name so the
342			// auto-categorization path will run. The mocked supabase chain
343			// has no .select().eq() for vendor_category_rules, so the inner ExpenseService
344			// calls will fail/throw — but the outer cleanup must NOT fire.
345			mockInsertSingle.mockResolvedValue({
346				data: { id: 'r1', family_id: 'fam-1', merchant_name: 'Test Store' },
347				error: null
348			});
349	
350			const file = new File(['x'], 'autocat.jpg', { type: 'image/jpeg' });
351			// Whether auto-cat throws all the way out or swallows internally,
352			// storage.remove must NOT be called because the receipt row exists.
353			await runWithRetries(file);
354	
355			expect(mockUpload).toHaveBeenCalled();
356			expect(mockRemove).not.toHaveBeenCalled();
357		});
358	});
